// Raw Line_Break class of cp, before LB1.
//
// The ranges partition the code space and are sorted by lower bound,
// so the covering range is unique and a binary search finds it.
inline Lb raw_class(std::uint32_t cp) {
  std::size_t lo = 0;
  std::size_t hi = kLbRanges.size();
  while (lo < hi) {
    const std::size_t mid = lo + (hi - lo) / 2;
    const auto &r = kLbRanges[mid];
    if (cp < r.lo) {
      hi = mid;
    } else if (cp > r.hi) {
      lo = mid + 1;
    } else {
      return r.cls;
    }
  }
  return kDefaultLb;
}

